/* Apply groups that contain at least one RPM_ZERO field. A group not in
   this mask can never become dirty, so the manager never waits on it. */
const unsigned int hc_cfg_rpm_zero_groups = 0x05FFu;

const hc_cfg_slot_t *hc_cfg_slot_at(unsigned int off)
{
    unsigned int lo = 0u;
    unsigned int hi = HC_CFG_SLOT_COUNT;

    /* Strictly bounded: the table is sorted by offset and the window
       halves every pass, so this cannot run longer than 9 iterations
       for 581 slots. No recursion, no allocation, safe from a task or
       from an interrupt. */
    while (lo < hi) {
        unsigned int mid = lo + ((hi - lo) >> 1);
        const hc_cfg_slot_t *s = &hc_cfg_slots[mid];
        if (off < s->offset) {
            hi = mid;
        } else if (off >= s->offset + s->size) {
            lo = mid + 1u;
        } else {
            return s;
        }
    }
    return (const hc_cfg_slot_t *)0;   /* a reserved byte */
}
